{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four category models, jointly lower learning rate to 5e-4 and raise dropout to 0.15. Smaller updates and stronger regularization may stabilize the newly unconstrained mask embedding. This configuration previously regressed with the earlier embedding parameterization, so its benefit remains uncertain. Preserve dimensions, history length, batch size, backbone, loss and training limits. Existing metadata and predictor loading remain compatible.",
      "edits": [
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.1\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.15\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"7e-4\"))",
          "replace": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"5e-4\"))"
        }
      ]
    }
  ],
  "change_summary": "Set shared BERT4Rec defaults to learning rate 5e-4 and dropout 0.15 for all four independently trained category models."
}
